"use client";

import { ThemeProvider as NextThemesProvider } from "next-themes";
import type { ComponentProps } from "react";

/**
 * Thin "use client" wrapper — next-themes' provider is a client component,
 * but the root layout that needs to render it is a server component and
 * can't import client-only code directly at the top level.
 *
 * `attribute="class"` toggles a `.dark` class on `<html>`, which is exactly
 * what globals.css's `@custom-variant dark (&:is(.dark *))` already expects
 * — no CSS changes needed, this was the missing piece.
 */
export function ThemeProvider({ children, ...props }: ComponentProps<typeof NextThemesProvider>) {
  return <NextThemesProvider {...props}>{children}</NextThemesProvider>;
}
